let expertLanguage = 'en';
try {const saved = localStorage.getItem('soshyant-expert-language'); if (saved === 'fa' || saved === 'en') expertLanguage = saved;} catch {}
const expertReverse = Object.fromEntries(Object.entries(expertTranslations).map(([fa, en]) => [en, fa]));
function currentLanguage() {return expertLanguage;}
function t(text) {
  if (typeof text !== 'string') return text;
  return expertLanguage === 'en' ? (expertTranslations[text] ?? text) : (expertReverse[text] ?? text);
}
const expertStatic = [];
function applyLanguage(language, persist = true) {
  expertLanguage = language === 'fa' ? 'fa' : 'en';
  if (persist) {try {localStorage.setItem('soshyant-expert-language', expertLanguage);} catch {}}
  document.documentElement.lang = expertLanguage;
  document.documentElement.dir = expertLanguage === 'fa' ? 'rtl' : 'ltr';
  document.title = expertLanguage === 'en' ? 'Soshyant Expert · Your private knowledge' : 'Soshyant Expert · دانش خصوصی شما';
  for (const item of expertStatic) {
    if (!item.node.isConnected) continue;
    if (item.attribute) item.node.setAttribute(item.attribute, t(item.source));
    else item.node.nodeValue = item.prefix + t(item.source) + item.suffix;
  }
  for (const select of document.querySelectorAll('.language-select')) select.value = expertLanguage;
  for (const id of ['authError','domainSaved','uploadPhase','toast']) {
    const node = document.getElementById(id);
    if (node && node.childNodes.length === 1 && node.firstChild.nodeType === Node.TEXT_NODE) node.textContent = t(node.textContent);
  }
  window.dispatchEvent(new Event('expert-language-change'));
}
{
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (['SCRIPT','STYLE'].includes(node.parentElement?.tagName)) continue;
    const source = node.nodeValue.trim();
    if (source in expertTranslations || source in expertReverse) {
      const start = node.nodeValue.indexOf(source);
      expertStatic.push({node, source, prefix:node.nodeValue.slice(0,start),suffix:node.nodeValue.slice(start+source.length)});
    }
  }
  for (const node of document.querySelectorAll('[placeholder],[aria-label]')) {
    for (const attribute of ['placeholder','aria-label']) {
      const source = node.getAttribute(attribute);
      if (source && (source in expertTranslations || source in expertReverse)) expertStatic.push({node,attribute,source});
    }
  }
  for (const select of document.querySelectorAll('.language-select')) select.addEventListener('change', () => applyLanguage(select.value));
  applyLanguage(expertLanguage, false);
}
